<template>
    <div class="login-page">
        <!-- 登录表单 -->
        <div class="login-container">
            <div class="center-container">
                <div class="logo-large">
                  <l-img :src="appLogo" :w="logoSize.width" :h="logoSize.height" />
                  <span class="logo-text">{{ appName }}</span>
                </div>

                <form class="login-form" @submit="handleFormSubmit">
                    <!-- 邮箱输入 -->
                    <div class="form-item">
                        <label class="form-label">{{ t('email') }}</label>
                        <div class="input-container">
                            <input
                                type="email"
                                v-model="loginForm.email"
                                :placeholder="t('emailPlaceholder')"
                                class="form-input"
                                :class="{ 'input-error': emailError }"
                                @blur="validateEmail"
                                required
                            />
                            <l-img class="clear-icon" v-if="loginForm.email" @click="clearEmail" src="/static/images/close_icon.png" w="20px" h="20px"></l-img>
                        </div>
                        <div class="error-message" v-if="emailError">{{ emailError }}</div>
                    </div>

                    <!-- 密码输入 -->
                    <div class="form-item">
                        <label class="form-label">
                          <span>{{ t('password') }}</span>
                        </label>



                        <div class="input-container">
                            <input
                                :type="passwordVisible ? 'text' : 'password'"
                                v-model="loginForm.password"
                                :placeholder="t('passwordPlaceholder')"
                                class="form-input"
                                :class="{ 'input-error': passwordError }"
                                @blur="validatePassword"
                                required
                            />
                            <div class="password-toggle" @click="togglePasswordVisibility">
                                <l-img
                                    v-if="!passwordVisible"
                                    src="/static/images/eye_icon1.png"
                                    w=" 20px"
                                    h= "20px"
                                />
                                <l-img v-else src="/static/images/eye_icon2.png" w="20px" h="20px" class="password-toggle-icon"></l-img>
                            </div>
                        </div>
                        <div class="error-message" v-if="passwordError">{{ passwordError }}</div>
                        <div class="forgot-password-container">
                            <span class="forgot-password" @click="clickForgotPassword">{{ t('forgotPassword') }}</span>
                        </div>
                    </div>

                    <!-- 登录按钮 -->
                    <div class="form-item">
                        <l-button
                            :text="t('login')"
                            :loadingText="t('loggingIn')"
                            :loading="loading"
                            :disabled="loading"
                            @onClick="clickSubmitLogin"
                            type="submit"
                        />
                    </div>


                </form>
            </div>
        </div>

        <!-- 关闭按钮 -->
        <div class="close-button" @click="clickClose">
          <el-icon color="#000000" size="24"><Close /></el-icon>
        </div>
    </div>
</template>

<script setup>
import { ref, reactive, defineAsyncComponent, onMounted, computed } from 'vue';
import { useI18n } from 'vue-i18n';
import { useRouter } from 'vue-router';
import {ROUTER_PATHS} from '../router/constants';
import { routerBack, getRouterParams } from '../router/navigation';
import { ApiUser } from '../api/api-user';
import { routerToTerms, routerToPrivacyPolicy } from '../router/navigation';

const { t } = useI18n();
const router = useRouter();
const appName = ref(process.env.VITE_APP_TITLE);
const appLogo = ref(process.env.VITE_APP_LOGO);

// 异步引入组件
const lImg = defineAsyncComponent(() => import('../components/l-img.vue'));
const lButton = defineAsyncComponent(() => import('../components/l-button.vue'));

// 表单数据
const loginForm = reactive({
    email: '',
    password: ''
});

// 错误信息
const emailError = ref('');
const passwordError = ref('');

// 密码可见性控制
const passwordVisible = ref(false);
const togglePasswordVisibility = () => {
    passwordVisible.value = !passwordVisible.value;
};

// 加载状态
const loading = ref(false);

// PC端logo尺寸
const logoSize = computed(() => {
    return { width: '60px', height: '60px' };
});

const clickForgotPassword = () => {
    router.push(ROUTER_PATHS.FORGOT_PASSWORD);
};

// 验证邮箱
const validateEmail = () => {
    if (!loginForm.email) {
        emailError.value = t('emailRequired');
        return false;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(loginForm.email)) {
        emailError.value = t('validEmail');
        return false;
    }

    emailError.value = '';
    return true;
};

// 验证密码
const validatePassword = () => {
    if (!loginForm.password) {
        passwordError.value = t('passwordRequired');
        return false;
    }

    if (loginForm.password.length < 6 || loginForm.password.length > 20) {
        passwordError.value = t('loginPasswordLength');
        return false;
    }

    passwordError.value = '';
    return true;
};

// 清除邮箱
const clearEmail = () => {
    loginForm.email = '';
};

// 登录方法
const clickSubmitLogin = async () => {
    const isEmailValid = validateEmail();
    const isPasswordValid = validatePassword();

    if (!isEmailValid || !isPasswordValid) {
        return;
    }

    try {
        // 显示加载状态
        loading.value = true;

        await ApiUser.login(loginForm.email, loginForm.password);

        // 获取重定向路径，如果没有则跳转到首页
        const routeParams = getRouterParams();
        const redirectPath = routeParams.redirect || ROUTER_PATHS.HOME;
        router.push(redirectPath);
    } catch (error) {
        console.error('Login failed:', error);
    } finally {
        loading.value = false;
    }
};


// 导航栏登录按钮点击
const clickLogin = () => {
    router.push(ROUTER_PATHS.LOGIN);
};

const clickGoToTerms = () => {
  routerToTerms();
};

const clickGoToPrivacyPolicy = () => {
  routerToPrivacyPolicy();
};

// 关闭按钮点击
const clickClose = () => {
    routerBack();
};

// 表单处理逻辑
const handleFormSubmit = (e) => {
  e.preventDefault(); // 阻止表单默认提交行为
  clickSubmitLogin();
};
onMounted(() => {
  console.log('VITE_BUILD_VERSION', import.meta.env.VITE_BUILD_VERSION);
});
</script>

